<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/db.php';
$adminUser = requireAdmin(); $adminPageTitle = 'Dialysis Centers';
$search = requestText($_GET, 'search', 100); $sql = 'SELECT * FROM dialysis_centers'; $params = [];
if ($search !== '') { $sql .= ' WHERE name LIKE :name_search OR address LIKE :address_search'; $searchValue = '%' . $search . '%'; $params['name_search'] = $searchValue; $params['address_search'] = $searchValue; } $sql .= ' ORDER BY name';
$stmt = $adminConnection->prepare($sql); $stmt->execute($params); $centers = $stmt->fetchAll(); require __DIR__ . '/includes/header.php';
?><div class="admin-toolbar"><form class="admin-toolbar"><label class="admin-field">Search centers<input name="search" value="<?= htmlspecialchars($search, ENT_QUOTES, 'UTF-8') ?>" placeholder="Name or location"></label><button class="admin-btn admin-btn-secondary">Search</button></form><button class="admin-btn" type="button" data-open-center-form>Add Dialysis Center</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Address</th><th>Contact</th><th>Hours</th><th>Machines / Slots</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($centers as $center): ?><tr><td><?= htmlspecialchars($center['name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($center['address'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($center['contact_number'], ENT_QUOTES, 'UTF-8') ?><br><?= htmlspecialchars($center['email'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($center['operating_hours'], ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $center['machine_count'] ?> / <?= (int) $center['available_slots'] ?></td><td><span class="admin-status admin-status-<?= strtolower($center['status']) ?>"><?= htmlspecialchars($center['status'], ENT_QUOTES, 'UTF-8') ?></span></td><td><a class="admin-btn admin-btn-secondary" href="edit_center.php?id=<?= (int) $center['id'] ?>">Edit</a> <form method="post" action="actions/delete_center.php" style="display:inline"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(getCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="center_id" value="<?= (int) $center['id'] ?>"><button class="admin-btn admin-btn-danger" data-confirm="Deactivate this center?">Deactivate</button></form></td></tr><?php endforeach; ?></tbody></table><?php if (!$centers): ?><p class="admin-empty">No dialysis centers found.</p><?php endif; ?></div><div class="admin-panel" id="center-form" hidden><div class="admin-panel-heading"><h2>Add Dialysis Center</h2></div><form method="post" action="actions/add_center.php" class="admin-form-grid"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(getCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><label class="admin-field">Name<input name="name" maxlength="191" required></label><label class="admin-field">Address<input name="address" maxlength="191" required></label><label class="admin-field">Contact number<input name="contact_number" maxlength="50" required></label><label class="admin-field">Email<input type="email" name="email" maxlength="191" required></label><label class="admin-field">Operating hours<input name="operating_hours" maxlength="100" placeholder="8:00 am - 5:00 pm" required></label><label class="admin-field">Dialysis types<input name="dialysis_types" maxlength="191" placeholder="Hemodialysis, Peritoneal Dialysis" required></label><label class="admin-field">Machines<input type="number" name="machine_count" min="0" required></label><label class="admin-field">Available slots<input type="number" name="available_slots" min="0" required></label><button class="admin-btn" type="submit">Save Center</button></form></div><?php require __DIR__ . '/includes/footer.php'; ?>
